<script>
import {onMount,tick} from 'svelte';
import {keyboardShortcut} from './lib/model.js';
import {data,profile,theme,setTheme,changeProfile,resetDemo,toast,storageUnavailable} from './lib/store.js';import {PROFILES,SERVICES,TASKS} from './lib/catalog.js';
import {ACADEMIC_PAGES,academicPage} from './lib/academics.js';import Academics from './pages/Academics.svelte';
import Icon from './lib/components/Icon.svelte';import Modal from './lib/components/Modal.svelte';import Home from './pages/Home.svelte';import Classes from './pages/Classes.svelte';import Progress from './pages/Progress.svelte';import Services from './pages/Services.svelte';import Account from './pages/Account.svelte';import CaseStudy from './pages/CaseStudy.svelte';
import {FINANCE_PAGES,PROFILE_PAGES,accountPage} from './lib/student-account.js';import WorkspaceNav from './lib/components/WorkspaceNav.svelte';import Finances from './pages/Finances.svelte';import Profile from './pages/Profile.svelte';
import {WORKSPACE_ROOTS,allWorkspacePages,workspacePage} from './lib/workspace-directory.js';import Tasks from './pages/Tasks.svelte';import WorkspaceDirectory from './pages/WorkspaceDirectory.svelte';
const shortcut=keyboardShortcut(navigator.platform);let tourOpen=$state(false);
let hash=$state(window.location.hash||'#/');let menu=$state(false);let searchOpen=$state(false);let query=$state('');let profileOpen=$state(false);let resetOpen=$state(false);let main;
const navigation=[{id:'',label:'Home',icon:'home'},{id:'academics',label:'My Academics',icon:'book'},{id:'finances',label:'My Finances',icon:'wallet'},{id:'profile',label:'My Profile',icon:'people'},...WORKSPACE_ROOTS,{id:'services',label:'Academic services',icon:'grid'}];
const otherNavigation=[{id:'scholarships',label:'Scholarships',icon:'star'}];
let route=$derived(hash.replace(/^#\/?/,'').split('?')[0].replace(/\/$/,''));let params=$derived(new URLSearchParams(hash.split('?')[1]??''));let title=$derived([...navigation,...otherNavigation,{id:'profile',label:'My profile'},{id:'case-study',label:'Project case study'}].find(n=>n.id===route)?.label??workspacePage(route)?.label??accountPage(route)?.label??academicPage(route)?.label??(route==='classes'?'Classes & schedule':route==='progress'?'Academic progress':'Page not found'));
let results=$derived([...navigation,...ACADEMIC_PAGES,...FINANCE_PAGES,...PROFILE_PAGES,...allWorkspacePages(),...otherNavigation,{id:'case-study',label:'Project case study',icon:'file'}].filter(x=>`${x.label} ${x.group??''} ${x.description??''}`.toLowerCase().includes(query.toLowerCase())));
let serviceResults=$derived(query.length>1?SERVICES.filter(s=>`${s.title} ${s.description}`.toLowerCase().includes(query.toLowerCase())):[]);
$effect(()=>{document.documentElement.dataset.theme=$theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',$theme==='dark'?'#240505':'#a0010f');document.title=`${title} · Catalyst`;});
onMount(()=>{const onhash=async()=>{hash=window.location.hash||'#/';menu=false;await tick();main?.focus();window.scrollTo({top:0,behavior:'instant'});};const onkey=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchOpen=!searchOpen;query='';}else if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();searchOpen=true;query='';}};window.addEventListener('hashchange',onhash);window.addEventListener('keydown',onkey);return()=>{window.removeEventListener('hashchange',onhash);window.removeEventListener('keydown',onkey);};});
function go(href){tourOpen=false;searchOpen=false;menu=false;profileOpen=false;window.location.hash=href;}
</script>
<a class="skip-link" href="#main-content" onclick={e=>{e.preventDefault();main?.focus();}}>Skip to main content</a>
<aside class="sidebar"><a class="brand" href="#/" aria-label="Catalyst home"><img class="uc-brand-mark" src="./uc-monogram.svg" alt="University of Cincinnati" width="44" height="39"/><div>Catalyst<small>Student workspace</small></div></a><div class="nav-caption">Workspace</div><WorkspaceNav {route} {params}/><div class="nav-caption nav-divider">Your essentials</div><nav aria-label="Student essentials">{#each otherNavigation as n}<a href={`#/${n.id}`} class:active={route===n.id} aria-current={route===n.id?'page':undefined}><Icon name={n.icon} size={19}/>{n.label}</a>{/each}</nav><div class="sidebar-bottom"><div class="sidebar-help"><span class="small">A little guidance?</span><p>Your next step is easier with support.</p><a href="#/services?category=Advising">Find academic advising<Icon name="arrow" size={15}/></a></div><a class="case-nav" href="#/case-study"><Icon name="file" size={16}/>About this redesign<Icon name="external" size={13}/></a><span class="sidebar-footer">University of Cincinnati<br/>Independent student prototype</span></div></aside>
<div class="app-main"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-menu" aria-label="Open navigation" onclick={()=>menu=true}><Icon name="menu"/></button><span class="workspace-label">My workspace</span><span class="breadcrumb-divider">/</span><span class="breadcrumb">{title}</span></div><div class="topbar-right"><button class="portal-search" aria-label={`Search the portal (${shortcut})`} onclick={()=>{searchOpen=true;query='';}}><Icon name="search" size={16}/><span>Search the portal</span><kbd>{shortcut}</kbd></button><button class="icon-button theme-button" aria-label={$theme==='light'?'Switch to dark theme':'Switch to light theme'} onclick={()=>setTheme($theme==='light'?'dark':'light')}><Icon name={$theme==='light'?'moon':'sun'} size={19}/></button><a class="icon-button notification-button" href="#/tasks/reminders" aria-label={`${TASKS.length-$data.completedTasks.length} remaining personal reminders`}><Icon name="bell" size={19}/>{#if $data.preferences.reminders&&$data.completedTasks.length<TASKS.length}<span></span>{/if}</a><button class="user-menu" aria-label="Choose demo student profile" onclick={()=>profileOpen=true}><span class="avatar">{$profile.initials}</span><span><strong>{$data.person.preferredName}</strong><small>{$profile.year} · Undergraduate</small></span><Icon name="down" size={14}/></button></div></header>
 {#if $storageUnavailable}<div class="storage-notice" role="alert">Browser storage is unavailable. Your changes work for this session but may be lost when the page reloads.</div>{/if}
 <main id="main-content" tabindex="-1" bind:this={main}>{#key hash+':'+$profile.id}{#if route===''}<Home/>{:else if route==='academics'||route.startsWith('academics/')}<Academics {route}/>{:else if route==='classes'}<Classes {params}/>{:else if route==='progress'}<Progress {params}/>{:else if route==='services'}<Services {params}/>{:else if route==='finances'||route.startsWith('finances/')}<Finances {route}/>{:else if route==='profile'||route.startsWith('profile/')}<Profile {route}/>{:else if route==='tasks'||route.startsWith('tasks/')}<Tasks {route}/>{:else if ['admissions','tools','quick-links'].includes(route.split('/')[0])}<WorkspaceDirectory {route}/>{:else if route==='scholarships'}<Account {route}/>{:else if route==='case-study'}<CaseStudy/>{:else}<div class="empty-state panel"><Icon name="search" size={32}/><h1>Let’s get you back on track.</h1><p>This page isn’t part of the prototype.</p><a href="#/" class="button primary">Go to your workspace<Icon name="arrow" size={16}/></a></div>{/if}{/key}</main>
 <footer class="app-footer"><span>Catalyst, reimagined. <span class="footer-light">A clearer path forward.</span></span><div><button onclick={()=>tourOpen=true}>Quick tour</button><a href="#/case-study">Case study</a><button onclick={()=>resetOpen=true}>Reset demo</button><span>Student project · 2026</span></div></footer>
</div>
<div class="toast-region" aria-live="polite" aria-atomic="true">{#if $toast}<div class="toast" class:error={$toast.kind==='error'}><Icon name={$toast.kind==='error'?'warning':'check'} size={19}/><span>{$toast.message}</span>{#if $toast.action}<button onclick={()=>{$toast.action();toast.set(null);}}>{$toast.actionLabel}</button>{/if}<button class="icon-button" aria-label="Dismiss notification" onclick={()=>toast.set(null)}><Icon name="close" size={16}/></button></div>{/if}</div>
{#if searchOpen}<Modal title="Where would you like to go?" onclose={()=>searchOpen=false}><div class="search-box command-search"><Icon name="search"/><input data-initial-focus aria-label="Search portal pages and services" type="search" placeholder="Search pages and services…" bind:value={query}/><kbd>Esc</kbd></div><span class="eyebrow command-label">Workspace</span><div class="command-results">{#each results as r}<button onclick={()=>go(r.href??`#/${r.id}`)}><Icon name={r.icon} size={19}/><span>{r.label}{#if r.group}<small>{r.group}</small>{/if}</span><Icon name="arrow" size={15}/></button>{/each}{#each serviceResults as s}<a href={s.href} target={s.external?'_blank':undefined} rel={s.external?'noreferrer':undefined} onclick={()=>searchOpen=false}><Icon name={s.icon} size={19}/><span>{s.title}<small>Academic service</small></span><Icon name={s.external?'external':'arrow'} size={15}/></a>{/each}{#if !results.length&&!serviceResults.length}<div class="empty-state"><p>No matching pages. Try “classes,” “grades,” or “advising.”</p></div>{/if}</div><p class="fine-print">Use Tab to move through results and Enter to open a destination.</p></Modal>{/if}
{#if profileOpen}<Modal title="Explore a student’s perspective" onclose={()=>profileOpen=false}><p class="modal-intro">Choose a synthetic profile. Each student’s plans, preferences, and enrollment stay separate in this browser.</p>{#each PROFILES as p}<button class="profile-choice" class:selected={$profile.id===p.id} onclick={()=>{changeProfile(p.id);profileOpen=false;}}><span class="avatar large">{p.initials}</span><span><strong>{p.name}</strong><small>{p.year} · {$profile.major}</small><small>{p.id==='arthur'?'Near the end of a five-year sample plan':'Starting the first year of a sample plan'}</small></span>{#if $profile.id===p.id}<Icon name="check"/>{/if}</button>{/each}<a href="#/profile" class="button secondary full spaced" onclick={()=>profileOpen=false}>View profile & preferences<Icon name="arrow" size={16}/></a></Modal>{/if}
{#if menu}<Modal title="Your workspace" onclose={()=>menu=false}><WorkspaceNav {route} {params} mobile ongo={()=>menu=false}/><nav class="mobile-navigation" aria-label="Services and personal navigation">{#each [...otherNavigation,{id:'case-study',label:'About this redesign',icon:'file'}] as n}<a href={`#/${n.id}`} aria-current={route===n.id?'page':undefined} onclick={()=>menu=false}><Icon name={n.icon}/>{n.label}<Icon name="arrow" size={16}/></a>{/each}</nav></Modal>{/if}
{#if resetOpen}<Modal title="Start this demo profile over?" onclose={()=>resetOpen=false}><p class="modal-intro">Reset {$profile.name}’s spring enrollment, cart, waitlists, saved resources, checklists, personal details, finance drafts, and saved what-if scenarios. The sample fall schedule stays intact. The other demo profile is unaffected.</p><div class="modal-actions"><button class="button secondary" onclick={()=>resetOpen=false}>Keep my changes</button><button class="button primary" onclick={()=>{resetDemo();resetOpen=false;}}>Reset this profile</button></div></Modal>{/if}

{#if tourOpen}<Modal title="A quick guide to your workspace" onclose={()=>tourOpen=false}><p class="modal-intro">Find familiar tasks in their new home. Open this guide any time from the footer.</p><ol class="quick-tour"><li><h3>Find and compare classes</h3><p>Open Classes & schedule. Choose a semester, search, then use Filters for meeting times and campus days.</p><button class="text-link" onclick={()=>go('#/classes')}>Find classes <Icon name="arrow" size={15}/></button></li><li><h3>Review, resolve, confirm</h3><p>A cart saves your plan. Review & enroll checks the whole selection; a confirmation receipt means enrollment is complete. My schedule shows confirmed classes and separate waitlists.</p></li><li><h3>Understand your next step</h3><p>Academic progress separates earned credits from coursework still underway. Tasks & reminders lets you set personal target dates. Academic services points you toward official support.</p><button class="text-link" onclick={()=>go('#/tasks')}>Set personal targets <Icon name="arrow" size={15}/></button></li></ol><div class="modal-actions"><button class="button primary" onclick={()=>tourOpen=false}>Got it</button></div></Modal>{/if}
